{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"mount_file_id":"1YTNJAba6f4hH9PAu2gzzu2oz_gKtjVDU","authorship_tag":"ABX9TyO9Z42e3vhNDNXBJi9VZJCC"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"id":"OjaN_IejLSeI","executionInfo":{"status":"ok","timestamp":1782918093986,"user_tz":-330,"elapsed":1647,"user":{"displayName":"D Girl","userId":"10979297630896453060"}},"outputId":"e24f2718-2144-44a8-8b16-d130bdd561e8","colab":{"base_uri":"https://localhost:8080/","height":564}},"outputs":[{"output_type":"stream","name":"stdout","text":["Rating Range Distribution:\n","  0-1: 2148 restaurants (22.49%)\n","  1-2: 10 restaurants (0.1%)\n","  2-3: 1891 restaurants (19.8%)\n","  3-4: 4388 restaurants (45.94%)\n","  4-5: 1114 restaurants (11.66%)\n","\n","Most common rating range: 3-4\n","Average votes per restaurant: 156.91\n"]},{"output_type":"display_data","data":{"text/plain":["<Figure size 1300x500 with 2 Axes>"],"image/png":"\n"},"metadata":{}}],"source":["import pandas as pd\n","import matplotlib.pyplot as plt\n","\n","# Load dataset\n","df = pd.read_csv('/content/Dataset .csv')\n","\n","# 1. Bin ratings into ranges\n","bins = [0, 1, 2, 3, 4, 5]\n","labels = ['0-1', '1-2', '2-3', '3-4', '4-5']\n","df['Rating Range'] = pd.cut(df['Aggregate rating'], bins=bins, labels=labels, include_lowest=True)\n","\n","rating_dist = df['Rating Range'].value_counts().sort_index()\n","rating_pct = (rating_dist / len(df) * 100).round(2)\n","\n","print(\"Rating Range Distribution:\")\n","for r, c, p in zip(rating_dist.index, rating_dist.values, rating_pct.values):\n","    print(f\"  {r}: {c} restaurants ({p}%)\")\n","\n","print(f\"\\nMost common rating range: {rating_dist.idxmax()}\")\n","print(f\"Average votes per restaurant: {df['Votes'].mean():.2f}\")\n","\n","# 2. Plots\n","colors = ['#d32f2f', '#ef6c00', '#f9a825', '#7cb342', '#1565c0']\n","fig, axes = plt.subplots(1, 2, figsize=(13, 5))\n","fig.suptitle('Restaurant Ratings Analysis', fontsize=14, fontweight='bold')\n","\n","# Bar chart\n","bars = axes[0].bar(rating_dist.index, rating_dist.values, color=colors, edgecolor='white')\n","axes[0].set_title('Distribution by Rating Range')\n","axes[0].set_xlabel('Rating Range')\n","axes[0].set_ylabel('Number of Restaurants')\n","for bar, pct in zip(bars, rating_pct.values):\n","    axes[0].text(bar.get_x() + bar.get_width()/2, bar.get_height() + 30,\n","                 f'{pct}%', ha='center', fontsize=9)\n","axes[0].set_ylim(0, rating_dist.max() * 1.15)\n","\n","# Histogram\n","axes[1].hist(df['Aggregate rating'], bins=20, color='#4C72B0', edgecolor='white')\n","axes[1].set_title('Histogram of Aggregate Ratings')\n","axes[1].set_xlabel('Aggregate Rating')\n","axes[1].set_ylabel('Frequency')\n","axes[1].axvline(df['Aggregate rating'].mean(), color='red', linestyle='--',\n","                label=f\"Mean: {df['Aggregate rating'].mean():.2f}\")\n","axes[1].legend()\n","\n","plt.tight_layout()\n","plt.savefig('ratings_analysis.png', dpi=150)\n","plt.show()"]}]}